BEGIN;
-- ===== Subject 6: Education, PGCE & Teaching
DELETE FROM subject_sections WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published');
UPDATE subjects SET about_title='About Education, PGCE & Teaching', about_body='<p>Education, PGCE and Teaching covers how people learn and how to teach them, from early years and primary classrooms to secondary schools, universities and adult learning.</p><p>Routes include teaching degrees, postgraduate teacher training (PGCE/PGDE), TESOL/TEFL, special educational needs, educational leadership and education technology.</p><p>Studying abroad lets you see different school systems and, in some countries, qualify for local teaching registration. Check each country''s rules, because a teaching qualification does not always transfer automatically.</p>', why_title='Why study Education, PGCE & Teaching?', why_body='<p><strong>Purposeful career.</strong> Teachers and education specialists shape learners'' lives and are needed in every country.</p><p><strong>Steady demand.</strong> Many countries report shortages in subjects such as maths, science, languages and special education.</p><p><strong>Portable skills.</strong> TESOL/TEFL and international-school routes make it possible to work in many countries.</p><p><strong>Varied paths.</strong> Beyond classrooms, graduates work in policy, educational technology, counselling, training and charities.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=6 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Education, PGCE & Teaching', about_body='<p>A Foundation in Education, PGCE &amp; Teaching. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Education, PGCE & Teaching?', why_body='<p>Foundation study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Education, PGCE & Teaching', about_body='<p>A Pathway in Education, PGCE &amp; Teaching. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Education, PGCE & Teaching?', why_body='<p>Pathway study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Education, PGCE & Teaching', about_body='<p>A Diploma in Education, PGCE &amp; Teaching. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Education, PGCE & Teaching?', why_body='<p>Diploma study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Education, PGCE & Teaching', about_body='<p>A Bachelor''s in Education, PGCE &amp; Teaching. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Education, PGCE & Teaching?', why_body='<p>Bachelor''s study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Education, PGCE & Teaching', about_body='<p>A Master''s in Education, PGCE &amp; Teaching. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Education, PGCE & Teaching?', why_body='<p>Master''s study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Education, PGCE & Teaching', about_body='<p>A MBA in Education, PGCE &amp; Teaching. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Education, PGCE & Teaching?', why_body='<p>MBA study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Education, PGCE & Teaching', about_body='<p>A PhD in Education, PGCE &amp; Teaching. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Education, PGCE & Teaching?', why_body='<p>PhD study in Education, PGCE &amp; Teaching lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=6 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
-- ===== Subject 7: Engineering
