INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=8 AND status='published'),'destination','Germany',NULL,'<p>Strong public research institutions (Max Planck, Fraunhofer) and low tuition at most public universities.</p><p>Most public universities charge little or no tuition (Baden-Württemberg charges non-EU students about €1,500 per semester), but you need to show living-cost funds. Graduates can stay up to 18 months to look for work in their field.</p>','published',5,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=8 AND status='published') AND name='Cell Biology'));
