INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=9 AND status='published'),'about','About Design',NULL,'<p>Design focuses on creative problem-solving across products, spaces and visual media. It sits within Creative Arts, Design &amp; Communication and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=9 AND status='published') AND name='Design'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=9 AND status='published'),'why','Why study Design?',NULL,'<p>Design builds specialist skills in creative problem-solving across products, spaces and visual media. Typical graduate roles include designer, creative lead, design researcher. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=9 AND status='published') AND name='Design'));
