INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=10 AND status='published'),'destination','Australia',NULL,'<p>Strong media and communication programmes with industry links.</p><p>Student visa fee is AUD 2,500 from 1 July 2026 and the national planning level is 295,000 new international students (kept for 2027). Graduates can apply for the Temporary Graduate visa (485); length depends on qualification and region.</p>','published',4);
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=10 AND status='published'),'destination','Ireland',NULL,'<p>English-speaking media sector with growing digital and content industries.</p><p>English-speaking, with a major European tech and finance base. The Stay Back scheme allows graduates to remain to seek work (up to 12 months after a bachelor''s, 24 months after a master''s or PhD).</p>','published',5);
