INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=10 AND status='published'),'destination','United Kingdom',NULL,'<p>Leading journalism and media schools with strong links to national news and broadcast organisations.</p><p>Post-study work: the Graduate Route currently gives 2 years (3 for PhD). For applications made from 1 January 2027 it is being shortened to 18 months for bachelor''s and master''s graduates; PhD stays at 3 years. Tuition for international students is typically £12,000–£40,000 a year depending on course and university.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=10 AND status='published') AND name='Digital Media'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=10 AND status='published'),'destination','United States',NULL,'<p>Well-known journalism and communication schools and a large media market.</p><p>Graduates can work on OPT for 12 months, with a 24-month STEM extension for eligible degrees. Visa and work-fee rules (OPT and H-1B) are under active review, so check USCIS before planning. International tuition is commonly $25,000–$65,000 a year.</p>','published',2,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=10 AND status='published') AND name='Digital Media'));
